package main

import (
	"fmt"
	"errors"
)

// divide mengembalikan hasil dan error
func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("tidak bisa membagi dengan nol")
	}
	return a / b, nil
}

// swap menukar dua string dan mengembalikan keduanya
func swap(a, b string) (string, string) {
	return b, a
}

func main() {
	// Test divide - sukses
	result, err := divide(10, 4)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Printf("10 / 4 = %.4f\n", result)
	}

	// Test divide - error
	_, err = divide(5, 0)
	if err != nil {
		fmt.Println("Error:", err)
	}

	// Test swap
	x, y := swap("Hello", "World")
	fmt.Println(x, y)
}
